<template>
	<q-page class="dashboard-page">
		<div class="dashboard-heading"><div><div class="eyebrow">{{ roleLabel }}</div><h1>Welcome, {{ displayName }}</h1></div><q-btn outline color="primary" icon="refresh" label="Refresh" @click="loadSummary" /></div>
		<div class="stat-grid dashboard-stats"><q-card v-for="stat in stats" :key="stat.label" class="summary-card" flat bordered><q-card-section><div class="summary-icon"><q-icon :name="stat.icon" /></div><div class="stat-value">{{ stat.value }}</div><div class="muted">{{ stat.label }}</div></q-card-section></q-card></div>
		<q-card class="activity-card" flat bordered><q-card-section class="activity-header"><div><h2>{{ activityTitle }}</h2><p class="muted">Live operational data from your banking workspace.</p></div><q-input v-model="filter" dense outlined placeholder="Filter records..." clearable /></q-card-section><q-separator /><q-table flat :rows="filteredRows" :columns="columns" row-key="id" :loading="loading" no-data-label="No recent records"><template #body-cell-status="props"><q-td :props="props"><q-badge :color="props.value === 'ACTIVE' || props.value === 'SUCCESS' ? 'positive' : 'grey-6'" :label="props.value || 'ACTIVE'" /></q-td></template></q-table></q-card>
	</q-page>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import { useAuthStore } from 'src/stores/auth-store'; import api from 'src/services/api'
const auth = useAuthStore(); const loading = ref(false); const filter = ref(''); const rows = ref([]); const counts = ref({ roles: 0, users: 0, accounts: 0, banks: 0 })
const displayName = computed(() => auth.username || 'System User'); const roleLabel = computed(() => auth.roleCode === 'ADMIN' ? 'SYSTEM ADMINISTRATION' : auth.roleCode === 'CUSTOMER' ? 'CUSTOMER PORTAL' : 'BANKING OPERATIONS'); const activityTitle = computed(() => auth.isCustomer ? 'My banking activity' : 'Overview & system operations')
const stats = computed(() => [{ label: 'Roles', value: counts.value.roles || '-', icon: 'security' }, { label: 'Users', value: counts.value.users || '-', icon: 'people' }, { label: 'Accounts', value: counts.value.accounts || '-', icon: 'account_balance_wallet' }, { label: 'Registered banks', value: counts.value.banks || '-', icon: 'account_balance' }])
const columns = [{ name: 'id', label: 'ID', field: 'id', align: 'left' }, { name: 'label', label: 'SYSTEM ENTITY', field: 'label', align: 'left' }, { name: 'type', label: 'TYPE', field: 'type', align: 'left' }, { name: 'status', label: 'STATUS', field: 'status', align: 'left' }, { name: 'updated', label: 'LAST UPDATED', field: 'updated', align: 'left' }]
const filteredRows = computed(() => rows.value.filter((row) => JSON.stringify(row).toLowerCase().includes(filter.value.toLowerCase())))
async function loadSummary () { loading.value = true; const endpoints = [['roles', '/roles/'], ['users', '/users/'], ['accounts', '/accounts/'], ['banks', '/banks/']]; try { const results = await Promise.all(endpoints.map(([, endpoint]) => api.get(endpoint).then((response) => response.data).catch(() => []))); endpoints.forEach(([name], index) => { counts.value[name] = results[index].length }); rows.value = results.flatMap((items, index) => items.slice(0, 4).map((item) => ({ id: item.id, label: `${endpoints[index][0].slice(0, -1)}: ${item.username || item.account_number || item.bank_name || item.role_code || item.type_name || item.id}`, type: endpoints[index][0], status: item.status || item.account_status || 'ACTIVE', updated: item.updated_at || item.created_at || item.opened_at || '-' }))) } finally { loading.value = false } }
onMounted(loadSummary)
</script>
